import { util } from '@aws-appsync/utils';

const VP_TABLE = 'LMASA-AISTACK-4VKHCQQY3CJR-VirtualParticipant';
const SHARE_INDEX_TABLE = 'LMASA-VirtualParticipantShareIndex';

// Same contract as the live VTL resolver: SharedWith is a full replace, not
// an additive list. We diff old vs. new here only to know which grantee
// mirror rows (VirtualParticipantShareIndex) need a VP id added or removed.
export function request(ctx) {
  const id = ctx.args.input.id;
  const newList = ctx.args.input.SharedWith ? ctx.args.input.SharedWith : [];
  const oldRaw = ctx.stash.oldSharedWith ? ctx.stash.oldSharedWith : '';
  const oldList = oldRaw
    .split(',')
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

  const added = newList.filter((g) => !oldList.includes(g));
  const removed = oldList.filter((g) => !newList.includes(g));

  const transactItems = [
    {
      table: VP_TABLE,
      operation: 'UpdateItem',
      key: util.dynamodb.toMapValues({ id }),
      update: {
        expression: 'SET SharedWith = :val',
        expressionValues: util.dynamodb.toMapValues({ ':val': newList.join(',') }),
      },
    },
  ];

  for (const grantee of added) {
    transactItems.push({
      table: SHARE_INDEX_TABLE,
      operation: 'UpdateItem',
      key: util.dynamodb.toMapValues({ PK: `u#${grantee}` }),
      update: {
        expression: 'ADD VpIds :ids',
        expressionValues: { ':ids': util.dynamodb.toStringSet([id]) },
      },
    });
  }

  for (const grantee of removed) {
    transactItems.push({
      table: SHARE_INDEX_TABLE,
      operation: 'UpdateItem',
      key: util.dynamodb.toMapValues({ PK: `u#${grantee}` }),
      update: {
        expression: 'DELETE VpIds :ids',
        expressionValues: { ':ids': util.dynamodb.toStringSet([id]) },
      },
    });
  }

  ctx.stash.newSharedWith = newList.join(',');
  return { operation: 'TransactWriteItems', transactItems };
}

export function response(ctx) {
  return {
    id: ctx.args.input.id,
    Owner: ctx.args.input.Owner,
    SharedWith: ctx.stash.newSharedWith,
  };
}
